<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import { useApiError } from '../composables/useApiError'
const name=ref('');const email=ref('');const password=ref('');const loading=ref(false);const router=useRouter();const auth=useAuthStore();const{error,capture}=useApiError();async function submit(){loading.value=true;error.value='';try{await auth.register(name.value,email.value,password.value);await router.push('/')}catch(e){capture(e)}finally{loading.value=false}}
</script>
<template><main class="auth-page"><section class="auth-intro"><div class="brand light"><span class="brand-mark">F</span><strong>Finora</strong></div><div><span class="eyebrow">INIZIA OGGI</span><h1>Dai un futuro<br>ai tuoi <em>progetti.</em></h1><p>Categorie, budget e movimenti in un unico posto sicuro.</p></div><small>© 2026 Finora</small></section><section class="auth-form"><form @submit.prevent="submit"><h2>Crea il tuo account</h2><p>Bastano pochi secondi per cominciare.</p><div v-if="error" class="error">{{ error }}</div><label>Nome<input v-model="name" placeholder="Il tuo nome" maxlength="100" required></label><label>Email<input v-model="email" type="email" placeholder="nome@esempio.it" required></label><label>Password<input v-model="password" type="password" minlength="8" maxlength="72" placeholder="Almeno 8 caratteri" required></label><button class="btn primary full" :disabled="loading">{{ loading?'Creazione…':'Crea account' }}</button><p class="auth-link">Hai già un account? <RouterLink to="/login">Accedi</RouterLink></p></form></section></main></template>
